        new_bound = set(bound)
        if isinstance(binds, SList):
            for pair in binds.children:
                if isinstance(pair, SList) and pair.children and isinstance(pair.children[0], Atom):
                    new_bound.add(pair.children[0].text)
        free: set[str] = set()
        for body in node.children[2:]:
            free |= _free_names(body, new_bound)
        # expressions of the bindings are evaluated in the outer scope
        if isinstance(binds, SList):
            for pair in binds.children:
                if isinstance(pair, SList) and len(pair.children) == 2:
                    free |= _free_names(pair.children[1], bound)
        return free
    free = set()
    for c in node.children:
        free |= _free_names(c, bound)
    return free
